namespace AutosurBuscador {
using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Imaging;using System.Globalization;using System.IO;using System.Linq;using System.Windows.Forms;

public static class GeneralPanel {
 public static readonly CultureInfo AR=CultureInfo.GetCultureInfo("es-AR");
 public static string Money(decimal value){return value.ToString("C2",AR);}
 public static string Percent(decimal? value){return value.HasValue?value.Value.ToString("N2",AR)+" %":"—";}
 public static readonly string[] Headers={"Sucursal","Objetivo ventas\nsin IVA","Facturación\nrepuestos","Diferencia\npara objetivo","Avance\nrepuestos","Objetivo\nutilidad","Utilidad","Margen\nreal","Diferencia\nutilidad"};
 public static string[] Cells(GeneralResult row){return new[]{row.Name,Money(row.Target),Money(row.Values.Sale),Money(row.Difference),Percent(row.Advance),Money(row.UtilityTarget),Money(row.Values.Profit),Percent(row.Values.Margin),Money(row.UtilityDifference)};}
 public static Bitmap Image(string brand,DateTime period,DateTime? cutoff,List<GeneralResult> rows,GeneralResult total){int[] widths={190,185,185,185,130,185,185,135,185};int width=widths.Sum()+40,height=160+(rows.Count+1)*46;var bitmap=new Bitmap(width,height);bitmap.SetResolution(144,144);using(var g=Graphics.FromImage(bitmap))using(var title=new Font("Segoe UI",17,FontStyle.Bold))using(var text=new Font("Segoe UI",10))using(var bold=new Font("Segoe UI",10,FontStyle.Bold))using(var small=new Font("Segoe UI",9))using(var center=new StringFormat{Alignment=StringAlignment.Center,LineAlignment=StringAlignment.Center})using(var right=new StringFormat{Alignment=StringAlignment.Far,LineAlignment=StringAlignment.Center})using(var left=new StringFormat{Alignment=StringAlignment.Near,LineAlignment=StringAlignment.Center}){g.Clear(Color.White);g.DrawString(brand+" · Objetivo general",title,Brushes.Black,20,12);g.DrawString("Cierre "+SalesMath.Start(period).ToString("dd/MM/yyyy")+" al "+SalesMath.End(period).ToString("dd/MM/yyyy")+(cutoff.HasValue?" · Datos hasta "+cutoff.Value.ToString("dd/MM/yyyy"):""),small,Brushes.DimGray,20,49);int x=20,y=80;for(int i=0;i<widths.Length;i++){var r=new Rectangle(x,y,widths[i],66);using(var b=new SolidBrush(i==7?Color.FromArgb(198,239,206):Color.FromArgb(157,195,230)))g.FillRectangle(b,r);g.DrawRectangle(Pens.Black,r);g.DrawString(Headers[i],bold,Brushes.Black,new RectangleF(x+5,y+3,widths[i]-10,60),center);x+=widths[i];}y+=66;var all=rows.Concat(new[]{total}).ToList();for(int n=0;n<all.Count;n++){bool last=n==all.Count-1;var row=all[n];var values=Cells(row);x=20;for(int c=0;c<widths.Length;c++){var r=new Rectangle(x,y,widths[c],46);Color fill=last?Color.FromArgb(255,243,64):c==7?Color.FromArgb(226,244,231):Color.White;using(var b=new SolidBrush(fill))g.FillRectangle(b,r);g.DrawRectangle(Pens.Black,r);Color ink=Color.FromArgb(27,38,51);if(c==3)ink=row.Difference>0?Color.FromArgb(205,42,49):Color.FromArgb(0,133,57);if(c==8)ink=row.UtilityDifference>0?Color.FromArgb(205,42,49):Color.FromArgb(0,133,57);if(c==7)ink=row.Values.Margin.HasValue&&row.Values.Margin.Value>=row.MarginGoal?Color.FromArgb(0,120,50):Color.FromArgb(190,40,45);using(var b=new SolidBrush(ink))g.DrawString(values[c],last?bold:text,b,new RectangleF(x+7,y+3,widths[c]-14,40),c==0?left:c==4||c==7?center:right);x+=widths[c];}y+=46;}}return bitmap;}
}

public class GeneralPreview:Form {
 readonly Bitmap bitmap;
 public GeneralPreview(Bitmap image){bitmap=image;Text="Panel de avances";Size=new Size(1200,650);MinimumSize=new Size(800,400);StartPosition=FormStartPosition.CenterParent;KeyPreview=true;var layout=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=2,ColumnCount=1};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,54));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));Controls.Add(layout);var bar=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(10)};layout.Controls.Add(bar,0,0);var save=new Button{Text="Guardar PNG",Width=145,Height=32};var copy=new Button{Text="Copiar imagen",Width=145,Height=32};var close=new Button{Text="Cerrar",Width=110,Height=32};bar.Controls.AddRange(new Control[]{save,copy,close});var panel=new Panel{Dock=DockStyle.Fill,AutoScroll=true,BackColor=Color.FromArgb(225,231,238)};var picture=new PictureBox{Image=bitmap,SizeMode=PictureBoxSizeMode.AutoSize,Location=new Point(12,12)};panel.Controls.Add(picture);layout.Controls.Add(panel,0,1);save.Click+=delegate{using(var dialog=new SaveFileDialog{Filter="Imagen PNG (*.png)|*.png",FileName="Objetivo_general_"+DateTime.Today.ToString("yyyyMMdd")+".png"})if(dialog.ShowDialog(this)==DialogResult.OK){try{bitmap.Save(dialog.FileName,ImageFormat.Png);}catch(Exception ex){MessageBox.Show(this,ex.Message,"Guardar panel");}}};copy.Click+=delegate{try{Clipboard.SetImage(bitmap);}catch(Exception ex){MessageBox.Show(this,ex.Message,"Copiar panel");}};close.Click+=delegate{Close();};}
 protected override bool ProcessCmdKey(ref Message message,Keys keys){if(keys==Keys.Escape){Close();return true;}return base.ProcessCmdKey(ref message,keys);}
 protected override void Dispose(bool disposing){if(disposing)bitmap.Dispose();base.Dispose(disposing);}
}

public class GeneralPage:UserControl {
 readonly string baseRoot,brand;readonly SalesStore data;GeneralSettings config;SalesStore rules;
 readonly DateTimePicker period=new DateTimePicker();readonly CheckedListBox branches=new CheckedListBox();readonly Label headline=new Label(),status=new Label();readonly DataGridView table=new DataGridView();readonly Button export=new Button();bool changing;List<GeneralBranch> available=new List<GeneralBranch>();List<GeneralResult> displayed=new List<GeneralResult>();GeneralResult total;GeneralPreview preview;
 public DateTime Period{get{return new DateTime(period.Value.Year,period.Value.Month,1);}}
 public GeneralPage():this(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Buscador Autosur Objetivos","datos"),"AUTOSUR RENAULT","RENAULT"){}
 readonly string expectedBrand;
 public GeneralPage(string root,string title,string expected){baseRoot=root;brand=title;expectedBrand=expected;Dock=DockStyle.Fill;BackColor=Color.FromArgb(243,246,250);Font=new Font("Segoe UI",10);try{rules=new SalesStore(baseRoot);data=new SalesStore(Path.Combine(baseRoot,"general"));config=new GeneralSettings(data.Root);}catch(Exception ex){Controls.Add(new Label{Dock=DockStyle.Fill,Text="No se pudo abrir Objetivo general.\n"+ex.Message});return;}Build();period.Value=SalesMath.Period(DateTime.Today);ReloadBranches();Enter+=delegate{try{rules=new SalesStore(baseRoot);RefreshData();}catch(Exception ex){status.Text=ex.Message;}};}
 Button ActionButton(string label,EventHandler action){var b=new Button{Text=label,Height=34,AutoSize=true,FlatStyle=FlatStyle.Flat,BackColor=Color.White,Margin=new Padding(0,0,8,0)};b.FlatAppearance.BorderColor=Color.FromArgb(205,215,228);b.Click+=action;return b;}
 void Build(){var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=5,Padding=new Padding(18,12,18,12)};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,48));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,48));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,94));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,65));Controls.Add(layout);layout.Controls.Add(new Label{Text="Objetivo general",Dock=DockStyle.Fill,Font=new Font("Segoe UI",24,FontStyle.Bold),ForeColor=Color.FromArgb(24,36,53)},0,0);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false,Margin=new Padding(0)};layout.Controls.Add(actions,0,1);actions.Controls.Add(ActionButton("Cargar reporte de la marca",Import));actions.Controls.Add(new Label{Text="Cierre",AutoSize=true,Margin=new Padding(4,8,8,0)});period.Format=DateTimePickerFormat.Custom;period.CustomFormat="MM/yyyy";period.ShowUpDown=true;period.Width=155;period.Margin=new Padding(0,4,12,0);actions.Controls.Add(period);actions.Controls.Add(ActionButton("Objetivos por sucursal",Parameters));export.Text="Generar panel de avances";export.AutoSize=true;export.Height=34;export.BackColor=Color.FromArgb(255,207,25);export.FlatStyle=FlatStyle.Flat;export.Click+=ShowPanel;actions.Controls.Add(export);headline.Dock=DockStyle.Fill;headline.BackColor=Color.White;headline.Padding=new Padding(14,10,14,5);headline.Font=new Font("Segoe UI",12,FontStyle.Bold);headline.ForeColor=Color.FromArgb(24,36,53);layout.Controls.Add(headline,0,2);var content=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,RowCount=1,Margin=new Padding(0,12,0,0)};content.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,215));content.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,12));content.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));layout.Controls.Add(content,0,3);var side=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=3,ColumnCount=1,BackColor=Color.White,Padding=new Padding(10)};side.RowStyles.Add(new RowStyle(SizeType.Absolute,31));side.RowStyles.Add(new RowStyle(SizeType.Absolute,38));side.RowStyles.Add(new RowStyle(SizeType.Percent,100));side.Controls.Add(new Label{Text="Sucursales",AutoSize=true,Font=new Font("Segoe UI",11,FontStyle.Bold)},0,0);var toggles=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false,Margin=new Padding(0)};var all=ActionButton("Todas",delegate{SelectAll(true);});var none=ActionButton("Ninguna",delegate{SelectAll(false);});all.AutoSize=none.AutoSize=false;all.Width=75;none.Width=90;toggles.Controls.Add(all);toggles.Controls.Add(none);side.Controls.Add(toggles,0,1);branches.Dock=DockStyle.Fill;branches.CheckOnClick=true;branches.BorderStyle=BorderStyle.None;branches.IntegralHeight=false;side.Controls.Add(branches,0,2);content.Controls.Add(side,0,0);table.Dock=DockStyle.Fill;table.ReadOnly=true;table.AllowUserToAddRows=false;table.AllowUserToDeleteRows=false;table.AllowUserToResizeRows=false;table.RowHeadersVisible=false;table.BackgroundColor=Color.White;table.BorderStyle=BorderStyle.None;table.EnableHeadersVisualStyles=false;table.ColumnHeadersHeight=68;table.ColumnHeadersDefaultCellStyle=new DataGridViewCellStyle{BackColor=Color.FromArgb(157,195,230),ForeColor=Color.FromArgb(24,36,53),Font=new Font("Segoe UI",9,FontStyle.Bold),WrapMode=DataGridViewTriState.True,Alignment=DataGridViewContentAlignment.MiddleCenter};table.DefaultCellStyle=new DataGridViewCellStyle{Font=new Font("Segoe UI",9),Alignment=DataGridViewContentAlignment.MiddleRight,SelectionBackColor=Color.FromArgb(224,239,255),SelectionForeColor=Color.Black};table.RowTemplate.Height=37;string[] headers=GeneralPanel.Headers.Concat(new[]{"Tickets","Ticket promedio"}).ToArray();int[] widths={155,160,160,160,115,160,160,115,160,75,160};for(int i=0;i<headers.Length;i++)table.Columns.Add(new DataGridViewTextBoxColumn{Name="c"+i,HeaderText=headers[i],Width=widths[i],SortMode=DataGridViewColumnSortMode.NotSortable});table.Columns[0].Frozen=true;table.Columns[0].DefaultCellStyle.Alignment=DataGridViewContentAlignment.MiddleLeft;content.Controls.Add(table,2,0);status.Dock=DockStyle.Fill;status.ForeColor=Color.FromArgb(90,107,130);status.Padding=new Padding(0,9,0,0);layout.Controls.Add(status,0,4);period.ValueChanged+=delegate{if(!changing)ReloadBranches();};branches.ItemCheck+=delegate{if(!changing&&IsHandleCreated)BeginInvoke(new Action(RefreshData));};}
 IEnumerable<SaleLine> AllLines(){return data.History.Values.SelectMany(s=>s.Lines);}
 void SelectAll(bool value){changing=true;for(int i=0;i<branches.Items.Count;i++)branches.SetItemChecked(i,value);changing=false;RefreshData();}
 void ReloadBranches(){changing=true;var checkedKeys=new HashSet<string>(branches.CheckedItems.Cast<GeneralBranch>().Select(b=>b.Key));bool initial=branches.Items.Count==0;available=GeneralMath.Branches(config,AllLines());branches.Items.Clear();foreach(var b in available)branches.Items.Add(b,initial||checkedKeys.Contains(b.Key));changing=false;RefreshData();}
 List<GeneralBranch> Selected(){return branches.CheckedItems.Cast<GeneralBranch>().ToList();}
 void RefreshData(){if(data==null||config==null)return;decimal margin=config.Margin(Period,rules.GetGoal(Period).Margin);var snapshot=data.Get(Period);var lines=snapshot==null?new List<SaleLine>():snapshot.Lines;var selected=Selected();displayed=GeneralMath.Rows(lines,selected,config,Period,margin,rules.Intern,rules.Warranty,rules.Courtesy);total=GeneralMath.Total(displayed,lines,selected.Select(b=>b.Key),Period,margin,rules.Intern,rules.Warranty,rules.Courtesy);table.Rows.Clear();foreach(var row in displayed.Concat(new[]{total})){int index=table.Rows.Add(GeneralPanel.Cells(row).Concat(new[]{row.Values.Tickets.ToString("N0",GeneralPanel.AR),row.Values.Average.HasValue?GeneralPanel.Money(row.Values.Average.Value):"—"}).Cast<object>().ToArray());var cells=table.Rows[index];cells.Cells[7].Style.BackColor=row.Values.Margin.HasValue&&row.Values.Margin.Value>=row.MarginGoal?Color.FromArgb(226,244,231):Color.FromArgb(255,233,233);cells.Cells[3].Style.ForeColor=row.Difference>0?Color.FromArgb(200,40,40):Color.FromArgb(0,130,55);cells.Cells[8].Style.ForeColor=row.UtilityDifference>0?Color.FromArgb(200,40,40):Color.FromArgb(0,130,55);if(row==total){cells.DefaultCellStyle.BackColor=Color.FromArgb(255,243,64);cells.DefaultCellStyle.Font=new Font("Segoe UI",9,FontStyle.Bold);}}table.ClearSelection();headline.Text="Venta: "+GeneralPanel.Money(total.Values.Sale)+"      Utilidad: "+GeneralPanel.Money(total.Values.Profit)+"      Margen: "+GeneralPanel.Percent(total.Values.Margin)+"\nObjetivo: "+GeneralPanel.Money(total.Target)+"      Avance: "+GeneralPanel.Percent(total.Advance)+"      "+(total.Difference>=0?"Falta: ":"Superado en: ")+GeneralPanel.Money(Math.Abs(total.Difference));status.Text=selected.Count+" de "+available.Count+" sucursales · Cierre "+SalesMath.Start(Period).ToString("dd/MM/yyyy")+" al "+SalesMath.End(Period).ToString("dd/MM/yyyy")+" · Margen objetivo "+margin.ToString("N2",GeneralPanel.AR)+" %\n"+(snapshot==null?"Cargá un reporte para este cierre. Los objetivos generales se guardan por sucursal y mes.":"Reporte hasta "+snapshot.Cutoff.ToString("dd/MM/yyyy")+" · "+Path.GetFileName(snapshot.Source))+" · Interno "+(rules.Intern?"incluido":"excluido")+", Garantía "+(rules.Warranty?"incluida":"excluida")+", Cortesía "+(rules.Courtesy?"incluida":"excluida");export.Enabled=snapshot!=null&&selected.Count>0;}
 void Import(object sender,EventArgs e){using(var dialog=new OpenFileDialog{Filter="Reporte Excel (*.xlsx)|*.xlsx",Title="Reporte de todas las sucursales de "+brand}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;try{Cursor=Cursors.WaitCursor;var report=GeneralReport.Read(dialog.FileName,expectedBrand);int inside=report.Lines.Count(l=>SalesMath.Period(l.Date)==Period),outside=report.Lines.Count-inside;bool all=false;using(var choice=new Form{Text="Cargar reporte general",Size=new Size(610,285),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false}){var info=new Label{Text="Cierre seleccionado: "+SalesMath.Start(Period).ToString("dd/MM/yyyy")+" al "+SalesMath.End(Period).ToString("dd/MM/yyyy")+"\nFilas dentro del cierre: "+inside+" · Fuera del cierre: "+outside+"\nSe reemplazarán los datos de cada cierre incluido, sin acumular duplicados.\nLos objetivos y la pestaña Objetivos actual se conservan.",Location=new Point(18,15),Size=new Size(560,100)};var include=new CheckBox{Text="Importar también los otros cierres presentes en el archivo",Location=new Point(18,124),Size=new Size(560,30),Checked=false};var ok=new Button{Text="Cargar",DialogResult=DialogResult.OK,Location=new Point(355,178),Size=new Size(105,34)};var cancel=new Button{Text="Cancelar",DialogResult=DialogResult.Cancel,Location=new Point(470,178),Size=new Size(105,34)};choice.Controls.AddRange(new Control[]{info,include,ok,cancel});choice.AcceptButton=ok;choice.CancelButton=cancel;if(choice.ShowDialog(this)!=DialogResult.OK)return;all=include.Checked;}ApplyReport(report,dialog.FileName,all);ReloadBranches();}catch(Exception ex){MessageBox.Show(this,"No se pudo cargar el reporte general.\n"+ex.Message,"Objetivo general",MessageBoxButtons.OK,MessageBoxIcon.Error);}finally{Cursor=Cursors.Default;}}}
 public void ApplyReport(GeneralReport report,string path,bool allPeriods){var lines=report.Lines.Where(l=>allPeriods||SalesMath.Period(l.Date)==Period).ToList();if(lines.Count==0)throw new Exception("El archivo no contiene ventas dentro del cierre seleccionado.");var previous=new Dictionary<string,Snapshot>(data.History);try{foreach(var g in lines.GroupBy(l=>SalesMath.Period(l.Date)))data.Set(new Snapshot{Period=g.Key,Cutoff=g.Max(l=>l.Date),Loaded=DateTime.UtcNow,Source=Path.GetFileName(path),Lines=g.ToList()});data.Save();}catch{data.History=previous;throw;}foreach(var name in report.Names)if(!config.Names.ContainsKey(name.Key))config.Names[name.Key]=name.Value;foreach(var l in lines)if(!config.Names.ContainsKey(GeneralMath.BranchKey(l)))config.Names[GeneralMath.BranchKey(l)]="Sucursal "+l.Branch;config.Save();ReloadBranches();}
 void Parameters(object sender,EventArgs e){if(available.Count==0){MessageBox.Show(this,"Primero cargá el reporte para identificar las sucursales.","Objetivos por sucursal");return;}using(var form=new Form{Text="Objetivos generales · "+Period.ToString("MMMM yyyy",GeneralPanel.AR),Size=new Size(800,570),StartPosition=FormStartPosition.CenterParent}){var layout=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=3,ColumnCount=1,Padding=new Padding(14)};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,52));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,52));form.Controls.Add(layout);var top=new FlowLayoutPanel{Dock=DockStyle.Fill};top.Controls.Add(new Label{Text="Margen objetivo único (%)",AutoSize=true,Margin=new Padding(0,8,8,0)});var margin=new NumericUpDown{Minimum=0,Maximum=100,DecimalPlaces=2,Value=config.Margin(Period,rules.GetGoal(Period).Margin),Width=100};top.Controls.Add(margin);layout.Controls.Add(top,0,0);var grid=new DataGridView{Dock=DockStyle.Fill,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,BackgroundColor=Color.White};grid.Columns.Add("code","Código");grid.Columns.Add("name","Nombre de sucursal");grid.Columns.Add("goal","Objetivo mensual en pesos");grid.Columns[0].ReadOnly=true;grid.Columns[0].FillWeight=55;grid.Columns[1].FillWeight=120;grid.Columns[2].FillWeight=105;grid.Columns[2].ValueType=typeof(decimal);grid.Columns[2].DefaultCellStyle.Format="N2";grid.Columns[2].DefaultCellStyle.FormatProvider=GeneralPanel.AR;foreach(var b in available)grid.Rows.Add(b.Code,b.Name,config.Target(Period,b.Key));layout.Controls.Add(grid,0,1);var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft,Padding=new Padding(0,10,0,0)};var cancel=ActionButton("Cancelar",delegate{form.Close();});var save=ActionButton("Guardar objetivos",delegate{try{grid.EndEdit();var values=new List<decimal>();var names=new List<string>();foreach(DataGridViewRow row in grid.Rows){string name=Convert.ToString(row.Cells[1].Value).Trim();decimal value;if(name.Length==0||!Decimal.TryParse(Convert.ToString(row.Cells[2].Value,GeneralPanel.AR),NumberStyles.Number,GeneralPanel.AR,out value)||value<0)throw new Exception("Completá nombres y objetivos válidos en todas las sucursales.");names.Add(name);values.Add(value);}for(int i=0;i<available.Count;i++){config.Names[available[i].Key]=names[i];config.SetTarget(Period,available[i].Key,values[i]);}config.SetMargin(Period,margin.Value);config.Save();form.Close();ReloadBranches();}catch(Exception ex){MessageBox.Show(form,ex.Message,"Objetivos");}});buttons.Controls.Add(cancel);buttons.Controls.Add(save);layout.Controls.Add(buttons,0,2);form.ShowDialog(this);}}
 void ShowPanel(object sender,EventArgs e){if(!export.Enabled)return;if(preview!=null&&!preview.IsDisposed)preview.Close();var snapshot=data.Get(Period);preview=new GeneralPreview(GeneralPanel.Image(brand,Period,snapshot==null?(DateTime?)null:snapshot.Cutoff,displayed,total));preview.Show(FindForm());}
 protected override void Dispose(bool disposing){if(disposing&&preview!=null&&!preview.IsDisposed)preview.Close();base.Dispose(disposing);}
}
